/* Snapshot of RRD-MOVIDOR-TEMPLATE taken 20260817-134535, before the rule + parameter fixes.
   49 parameters, 195 options, 59 rules, 80 conditions.
   Running this file restores exactly that state. */
SET NOCOUNT ON;
DECLARE @Cfg INT = (SELECT TOP 1 CfgID FROM dbo.uCfgConfigurators WHERE PartID = N'RRD-MOVIDOR-TEMPLATE');
DECLARE @P INT;

DELETE o FROM dbo.uCfgParameterOptions o JOIN dbo.uCfgParameters p ON o.ParamID=p.ParamID WHERE p.CfgID=@Cfg;
DELETE FROM dbo.uCfgParameters WHERE CfgID=@Cfg;
DELETE rc FROM dbo.uCfgRuleConditions rc JOIN dbo.uCfgRules r ON rc.RuleID=r.RuleID WHERE r.CfgID=@Cfg;
DELETE FROM dbo.uCfgRules WHERE CfgID=@Cfg;

